from pathlib import Path
for name in ['replaygain-which-is-not-lossless.fuzz','flac-foreign-metadata-wav-8bps.fuzz','flac-foreign-metadata-aiff-8bps.fuzz']:
 b=Path('repo-vul/src-vul/flac/oss-fuzz/seedcorpus/fuzzer_tool_flac/'+name).read_bytes()
 start=b.find(b'fLaC')
 print('\n',name,'fLaC',start,'len',len(b))
 if start>=0:
  p=start+4
